/**
 * @suppress
 */
public object FfiConverterTypeNwcNode: FfiConverter<NwcNode, Pointer> {

    override fun lower(value: NwcNode): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): NwcNode {
        return NwcNode(value)
    }

    override fun read(buf: ByteBuffer): NwcNode {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: NwcNode) = 8UL

    override fun write(value: NwcNode, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}


